#pragma once
// CTRL18-UI (T7): which controller glyph set (button pictures) to show. Pure functions, header-only, no SDL/GL.
//
// Sets are folders <game root>/textures/glyphs/<game id>/<folder>/ with Dolphin-named PNGs (generated by
// outputs/pc-tools/glyphs/make_glyph_sets.py from Kenney's CC0 "Input Prompts"). The folder name is
// <device>-<preset family>: "ps-hd", "xbox-hd", "switch-hd", "kbm" for the presets "Switch HD (knoppen)" and
// "Toetsenbord + muis", and "ps-classic", "xbox-classic", "switch-classic", "kbm-classic" for "Klassiek" and
// "Wii (beweging/gyro)". "" = no set (the game's own Wii pictures).
//
// Setting [graphics] glyph_set (env NWII_GLYPH_SET overrides):
//   "auto" (default)  the device the player used last (launcher / game input; no input yet: a connected controller,
//                     else keyboard + mouse), with the preset of that device ([input] preset_gamepad / preset_keyboard)
//   "ps" | "xbox" | "switch" | "kbm"   that device, with its preset
//   "wii"             the original Wii Remote pictures (no set)
//   any folder name   exactly that folder (tests, own sets)
#include <cstring>
#include <string>

namespace nwii::runtime::glyphs {

enum class Device { Keyboard, PlayStation, Xbox, Switch };

// Controller type strings of input/controller_events.h ("PS5", "PS4", "Xbox", "Switch Pro", "Joy-Con", "Controller").
// Unknown / generic pads use the Xbox pictures (XInput layout).
inline Device DeviceFromType(const char* type) {
    if (!type || !*type) return Device::Xbox;
    if (std::strncmp(type, "PS", 2) == 0) return Device::PlayStation;
    if (std::strstr(type, "Switch") || std::strstr(type, "Joy-Con")) return Device::Switch;
    return Device::Xbox;
}

inline const char* DeviceName(Device d) {
    switch (d) {
    case Device::Keyboard: return "kbm";
    case Device::PlayStation: return "ps";
    case Device::Xbox: return "xbox";
    case Device::Switch: return "switch";
    }
    return "kbm";
}

// Folder for a device under the given presets. preset_gamepad "switch-hd" -> "-hd", anything else ("classic",
// "wii-motion") -> "-classic"; preset_keyboard "kbm" -> "kbm", anything else -> "kbm-classic".
inline std::string FolderFor(Device d, const std::string& preset_gamepad, const std::string& preset_keyboard) {
    if (d == Device::Keyboard) return preset_keyboard == "classic" ? "kbm-classic" : "kbm";
    return std::string(DeviceName(d)) + (preset_gamepad == "classic" || preset_gamepad == "wii-motion" ? "-classic" : "-hd");
}

// The folder for a setting value; `last_used` is the device for "auto". Returns "" for "wii"/"off"/"none".
inline std::string ResolveFolder(const std::string& setting, Device last_used, const std::string& preset_gamepad,
                                 const std::string& preset_keyboard) {
    if (setting == "wii" || setting == "off" || setting == "none" || setting == "original") return "";
    if (setting.empty() || setting == "auto") return FolderFor(last_used, preset_gamepad, preset_keyboard);
    if (setting == "ps" || setting == "playstation") return FolderFor(Device::PlayStation, preset_gamepad, preset_keyboard);
    if (setting == "xbox") return FolderFor(Device::Xbox, preset_gamepad, preset_keyboard);
    if (setting == "switch" || setting == "nintendo") return FolderFor(Device::Switch, preset_gamepad, preset_keyboard);
    if (setting == "kbm" && preset_keyboard == "classic") return "kbm-classic";
    return setting; // "kbm" or an explicit folder name
}

// True for the setting values the UI offers (anything else is taken as a folder name).
inline bool IsKnownSetting(const std::string& s) {
    return s == "auto" || s == "wii" || s == "ps" || s == "xbox" || s == "switch" || s == "kbm";
}

} // namespace nwii::runtime::glyphs
